-- Synthetic v0.1 test baseline. Only use in a new development database.
CREATE TABLE users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,username VARCHAR(30) UNIQUE,password_hash VARCHAR(255),display_name VARCHAR(100),role VARCHAR(16),status INT DEFAULT 1);
 CREATE TABLE auth_sessions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED,token_hash VARCHAR(64),expires_at DATETIME,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
 CREATE TABLE remember_devices(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED,token_hash VARCHAR(64),device_name VARCHAR(255),user_agent VARCHAR(500),expires_at DATETIME,last_used_at DATETIME,revoked_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
 CREATE TABLE files(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,category VARCHAR(1),original_name VARCHAR(191),stored_name VARCHAR(191),storage_path VARCHAR(500),file_type VARCHAR(32),mime_type VARCHAR(100),file_size BIGINT,uploader_id BIGINT UNSIGNED,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
